 await registerLeaveWorkflowRoutes(app,db,config);
 await registerLeaveWorkspaceRoutes(app,db,config);
 await registerWorkflowTaskRoutes(app,db,config);
 await registerFeeRoutes(app,db,config);
 await registerCertificateRoutes(app,db,config);
 await registerReportRoutes(app,db,config);
 async function coreMutation(req:FastifyRequest,p:Principal,action:string,entityType:string,work:(tx:Queryable)=>Promise<any>,summary:Record<string,unknown>={}){return db.transaction(async tx=>{const row=await work(tx);await writeAudit(tx,{schoolId:p.schoolId,actorUserId:p.userId,action,entityType,entityId:row.id,outcome:'SUCCESS',correlationId:req.correlationId,summary:{...summary,version:row.version}});return row})}
 app.get('/health',async()=>({status:'ok',apiVersion:'v1'}));
 app.post('/api/v1/setup',async(req,reply)=>{const input=parsed(setup,req.body);if(!validatePassword(input.password))throw new ApiError('WEAK_PASSWORD','Use at least 12 characters with upper, lower, number, and symbol.',422);const count=await db.query<{count:string}>('SELECT count(*)::text count FROM schools');if(Number(count.rows[0]?.count||0)>0)throw new ApiError('SETUP_ALREADY_COMPLETED','Initial administrator setup is already complete.',409);const ids={school:randomUUID(),role:randomUUID(),user:randomUUID()};await db.transaction(async tx=>{await tx.query('INSERT INTO schools(id,name,slug) VALUES($1,$2,$3)',[ids.school,input.schoolName,input.schoolSlug]);await tx.query('INSERT INTO roles(id,school_id,name,system,active) VALUES($1,$2,$3,true,true)',[ids.role,ids.school,'System Administrator']);await tx.query('INSERT INTO users(id,school_id,role_id,username,password_hash) VALUES($1,$2,$3,$4,$5)',[ids.user,ids.school,ids.role,input.username,await hashPassword(input.password)]);await writeAudit(tx,{schoolId:ids.school,actorUserId:ids.user,action:'FIRST_ADMIN_CREATED',entityType:'User',entityId:ids.user,outcome:'SUCCESS',correlationId:req.correlationId});});return reply.code(201).send({data:{schoolId:ids.school,userId:ids.user}});});
 app.post('/api/v1/auth/login',async(req,reply)=>{const input=parsed(credentials,req.body),key=req.ip+'|'+input.schoolSlug+'|'+input.username.toLowerCase(),now=Date.now(),attempt=loginAttempts.get(key);if(attempt&&now-attempt.since<600000&&attempt.count>=5)throw new ApiError('LOGIN_RATE_LIMITED','Sign-in is temporarily unavailable. Try again later.',429);const found=await db.query<any>('SELECT u.*,r.name role_name FROM users u JOIN schools s ON s.id=u.school_id JOIN roles r ON r.id=u.role_id WHERE s.slug=$1 AND lower(u.username)=lower($2)',[input.schoolSlug,input.username]);const u=found.rows[0],valid=!!u&&await verifyPassword(u.password_hash,input.password).catch(()=>false);if(!valid){loginAttempts.set(key,{count:(attempt?.count||0)+1,since:attempt?.since||now});await writeAudit(db,{schoolId:u?.school_id||null,actorUserId:u?.id||null,action:'LOGIN_FAILURE',entityType:'User',entityId:u?.id,outcome:'FAILED',reasonCode:'INVALID_CREDENTIALS',correlationId:req.correlationId});throw new ApiError('INVALID_CREDENTIALS','Invalid school, username, or password.',401);}if(u.status!=='Active')throw new ApiError('ACCOUNT_DISABLED','This account is disabled.',403);loginAttempts.delete(key);const session=await createSession(db,u,config.sessionTtlMinutes,{ip:req.ip,userAgent:req.headers['user-agent']});setSessionCookie(reply,config,session.token,session.expiresAt);await writeAudit(db,{schoolId:u.school_id,actorUserId:u.id,action:'LOGIN_SUCCESS',entityType:'User',entityId:u.id,outcome:'SUCCESS',correlationId:req.correlationId});return{data:{user:{id:u.id,username:u.username,role:u.role_name,mustChangePassword:u.must_change_password,teacherId:u.teacher_id||null,studentId:u.student_id||null,guardianId:(await db.query<any>('SELECT guardian_id FROM user_guardian_links WHERE user_id=$1 AND school_id=$2',[u.id,u.school_id])).rows[0]?.guardian_id||null,permissions:(await permissionsForUser(db,{schoolId:u.school_id,userId:u.id,roleName:u.role_name,permissions:[]})).permissions},csrfToken:session.csrf,expiresAt:session.expiresAt.toISOString()}};});
 app.get('/api/v1/auth/session',{preHandler:auth(db,config)},async req=>{const p=principal(req),csrfToken=await rotateCsrf(db,req.sessionToken!);return{data:{user:{id:p.userId,username:p.username,role:p.roleName,teacherId:p.teacherId,studentId:p.studentId,guardianId:p.guardianId,permissions:p.permissions},authenticated:true,csrfToken}};});
 app.post('/api/v1/auth/logout',{preHandler:auth(db,config,true)},async(req,reply)=>{const p=principal(req);await revokeSession(db,req.sessionToken!);clearSessionCookie(reply,config);await writeAudit(db,{schoolId:p.schoolId,actorUserId:p.userId,action:'LOGOUT',entityType:'User',entityId:p.userId,outcome:'SUCCESS',correlationId:req.correlationId});return{data:{loggedOut:true}};});
 app.post('/api/v1/auth/change-password',{preHandler:auth(db,config,true)},async(req)=>{const p=principal(req),input=parsed(z.object({currentPassword:z.string().min(1),newPassword:z.string().max(256)}).strict(),req.body);if(!validatePassword(input.newPassword))throw new ApiError('WEAK_PASSWORD','Use at least 12 characters with upper, lower, number, and symbol.',422);const row=await db.query<any>('SELECT password_hash FROM users WHERE id=$1 AND school_id=$2',[p.userId,p.schoolId]);if(!await verifyPassword(row.rows[0].password_hash,input.currentPassword))throw new ApiError('INVALID_CREDENTIALS','The current password is incorrect.',401);await db.transaction(async tx=>{await tx.query('UPDATE users SET password_hash=$1,must_change_password=false,updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE id=$2',[await hashPassword(input.newPassword),p.userId]);await revokeOtherSessions(tx,p.userId,req.sessionToken!);await writeAudit(tx,{schoolId:p.schoolId,actorUserId:p.userId,action:'PASSWORD_CHANGED',entityType:'User',entityId:p.userId,outcome:'SUCCESS',correlationId:req.correlationId});});return{data:{changed:true}};});
 app.post('/api/v1/auth/accept-invitation',async req=>{const input=parsed(z.object({token:z.string().min(32).max(256),newPassword:z.string().max(256)}).strict(),req.body);if(!validatePassword(input.newPassword))throw new ApiError('WEAK_PASSWORD','Use at least 12 characters with upper, lower, number, and symbol.',422);const invitation=await db.query<any>('SELECT * FROM password_invitations WHERE id_hash=$1 AND used_at IS NULL AND expires_at>now()',[digest(input.token)]);const invite=invitation.rows[0];if(!invite)throw new ApiError('INVITATION_INVALID','This password invitation is invalid or expired.',400);await db.transaction(async tx=>{await tx.query("UPDATE users SET password_hash=$1,must_change_password=false,status='Active',updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE id=$2 AND school_id=$3",[await hashPassword(input.newPassword),invite.user_id,invite.school_id]);await tx.query('UPDATE password_invitations SET used_at=CURRENT_TIMESTAMP WHERE id_hash=$1',[invite.id_hash]);await tx.query('DELETE FROM sessions WHERE user_id=$1',[invite.user_id]);await writeAudit(tx,{schoolId:invite.school_id,actorUserId:invite.user_id,action:'PASSWORD_INVITATION_ACCEPTED',entityType:'User',entityId:invite.user_id,outcome:'SUCCESS',correlationId:req.correlationId});});return{data:{passwordSet:true}};});

 app.get('/api/v1/users',{preHandler:auth(db,config)},async req=>({data:await entityList(db,principal(req),'users','id,role_id AS "roleId",teacher_id AS "teacherId",username,status,created_at AS "createdAt",updated_at AS "updatedAt",version')}));
 app.post('/api/v1/users/:id/password-invitation',{preHandler:auth(db,config,true)},async(req,reply)=>{const p=principal(req);requirePermission(p,'users:manage');const userId=String((req.params as any).id),found=await db.query<any>('SELECT id FROM users WHERE id=$1 AND school_id=$2',[userId,p.schoolId]);if(!found.rows[0])throw new ApiError('USER_NOT_FOUND','User not found.',404);const token=randomBytes(32).toString('base64url'),expiresAt=new Date(Date.now()+24*60*60_000);await db.transaction(async tx=>{await tx.query('DELETE FROM password_invitations WHERE user_id=$1 AND used_at IS NULL',[userId]);await tx.query('INSERT INTO password_invitations(id_hash,user_id,school_id,expires_at,created_by) VALUES($1,$2,$3,$4,$5)',[digest(token),userId,p.schoolId,expiresAt,p.userId]);await writeAudit(tx,{schoolId:p.schoolId,actorUserId:p.userId,action:'PASSWORD_INVITATION_CREATED',entityType:'User',entityId:userId,outcome:'SUCCESS',correlationId:req.correlationId,summary:{expiresAt:expiresAt.toISOString()}});});return reply.code(201).send({data:{token,expiresAt:expiresAt.toISOString()}});});
 app.get('/api/v1/staff',{preHandler:auth(db,config)},async req=>{const p=principal(req);await authorizeWorkspaceAction(db,p,'staff','staff','record.view');return{data:await core.list(p,'staff')}});
 app.post('/api/v1/staff',{preHandler:auth(db,config,true)},async(req,reply)=>{const p=principal(req);await authorizeCreate(db,p,await coreSecurityContext(db,p,'staff','staff','staff'));const input=parsed(staff,req.body),row=await coreMutation(req,p,'STAFF_CREATED','Staff',async tx=>{if(!input.employeeNumber){const school=(await tx.query<any>('SELECT settings FROM schools WHERE id=$1',[p.schoolId])).rows[0],prefix=String(school?.settings?.employeePrefix||'EMP').slice(0,20);do{input.employeeNumber=await nextWorkspaceNumber(tx,p.schoolId,'staff',prefix+'{000}')}while((await tx.query('SELECT id FROM staff WHERE school_id=$1 AND employee_number=$2',[p.schoolId,input.employeeNumber])).rows.length)}const custom=await validateOperationalCustomValues(tx,p,'staff',input.customValues||{},input,'create');return core.createStaff(tx,p,{...input,extra:{...(input.extra||{}),workspaceCustomFields:custom}})},{employeeNumber:input.employeeNumber||null});return reply.code(201).send({data:row})});
 app.patch('/api/v1/staff/:id',{preHandler:auth(db,config,true)},async req=>{const p=principal(req),input=parsed(staff.partial().extend({version:z.number().int().positive()}).strict(),req.body),id=String((req.params as any).id),context=await coreSecurityContext(db,p,'staff','staff','staff',id);await authorizeUpdate(db,p,context,context);return{data:await coreMutation(req,p,'STAFF_UPDATED','Staff',async tx=>{if(input.customValues!==undefined){const old=(await tx.query<any>('SELECT extra FROM staff WHERE id=$1 AND school_id=$2',[id,p.schoolId])).rows[0]?.extra||{},custom=await validateOperationalCustomValues(tx,p,'staff',input.customValues,{...input,id},'edit');input.extra={...old,workspaceCustomFields:{...(old.workspaceCustomFields||{}),...custom}}}return core.updateStaff(tx,p,id,input)})}});
 app.post('/api/v1/staff/:id/deactivate',{preHandler:auth(db,config,true)},async req=>{const p=principal(req),id=String((req.params as any).id);await authorizeRecord(db,p,'record.archive',await coreSecurityContext(db,p,'staff','staff','staff',id));const input=parsed(versionOnly,req.body);return{data:await coreMutation(req,p,'STAFF_DEACTIVATED','Staff',tx=>core.deactivateStaff(tx,p,id,input.version))}});
 app.post('/api/v1/staff/:id/restore',{preHandler:auth(db,config,true)},async req=>{const p=principal(req),id=String((req.params as any).id);await authorizeRecord(db,p,'record.restore',await coreSecurityContext(db,p,'staff','staff','staff',id));const input=parsed(versionOnly,req.body);return{data:await coreMutation(req,p,'STAFF_RESTORED','Staff',tx=>core.restoreStaff(tx,p,id,input.version))}});
 app.post('/api/v1/staff/:id/print-event',{preHandler:auth(db,config,true)},async req=>{const p=principal(req),id=String((req.params as any).id);await authorizeRecord(db,p,'record.print',await coreSecurityContext(db,p,'staff','staff','staff',id));const found=await db.query('SELECT id FROM staff WHERE id=$1 AND school_id=$2',[id,p.schoolId]);if(!found.rows[0])throw new ApiError('RECORD_NOT_FOUND','Staff record not found.',404);await writeAudit(db,{schoolId:p.schoolId,actorUserId:p.userId,action:'STAFF_PRINTED',entityType:'Staff',entityId:id,outcome:'SUCCESS',correlationId:req.correlationId});return{data:{recorded:true}}});

